// Ease Safety: a fixed, reviewable when-to-seek-help pathway.
// These rules are deliberately NOT generated by AI — they are structured
// guidance that runs before any comfort recommendation.

export type Urgency = "urgent" | "prompt" | "routine";

export type SafetyAnswers = {
  /** Sudden, severe discomfort (came on quickly and is very strong) */
  suddenSevere: boolean;
  /** Fainting, fever or vomiting together with the discomfort */
  faintFeverVomit: boolean;
  /** Pregnant now, or a chance of being pregnant */
  possiblyPregnant: boolean;
  /** Numbness around the groin, loss of bladder/bowel control, or new leg/arm weakness */
  nerveWarnings: boolean;
  /** Chest discomfort, or trouble breathing */
  chestOrBreathing: boolean;
  /** A joint that is hot, red and very swollen, or unable to bear weight */
  jointWarnings: boolean;
  /** Symptoms that are new, getting worse, or have lasted more than two weeks */
  persistent: boolean;
};

export type SafetyResult = {
  level: Urgency;
  title: string;
  message: string;
  steps: string[];
};

export const blankAnswers: SafetyAnswers = {
  suddenSevere: false,
  faintFeverVomit: false,
  possiblyPregnant: false,
  nerveWarnings: false,
  chestOrBreathing: false,
  jointWarnings: false,
  persistent: false,
};

export const safetyQuestions: { key: keyof SafetyAnswers; text: string }[] = [
  { key: "chestOrBreathing", text: "Do you have chest discomfort, or are you finding it hard to breathe?" },
  { key: "nerveWarnings", text: "Do you have numbness around your groin or bottom, trouble controlling your bladder or bowels, or new weakness in a leg or arm?" },
  { key: "suddenSevere", text: "Did the discomfort start suddenly and feel very strong?" },
  { key: "faintFeverVomit", text: "Do you also have fainting or dizziness, a fever, or vomiting?" },
  { key: "possiblyPregnant", text: "Are you pregnant now, or is there a chance you could be?" },
  { key: "jointWarnings", text: "Do you have a joint that is hot, red and very swollen, or are you unable to put weight on it?" },
  { key: "persistent", text: "Is this symptom new, getting worse, or has it lasted more than two weeks?" },
];

const urgent = (message: string, steps: string[]): SafetyResult => ({
  level: "urgent",
  title: "Seek urgent medical care now",
  message,
  steps,
});

export function assessSafety(a: SafetyAnswers): SafetyResult {
  if (a.chestOrBreathing) {
    return urgent(
      "Chest discomfort or trouble breathing can be serious. Please get medical help straight away — do not wait to see if it passes.",
      ["Go to the nearest emergency unit or clinic now, or ask someone to take you.", "If you are alone, call someone you trust to stay with you.", "Do not drive yourself if you feel unwell."],
    );
  }
  if (a.nerveWarnings) {
    return urgent(
      "Numbness around the groin, loss of bladder or bowel control, or new weakness can be a sign that nerves are under pressure. This needs same-day assessment.",
      ["Go to a hospital or clinic today.", "Avoid heavy lifting or straining on the way.", "Tell the health worker exactly when these changes started."],
    );
  }
  if (a.suddenSevere && (a.faintFeverVomit || a.possiblyPregnant)) {
    return urgent(
      "Sudden, severe discomfort together with fainting, fever, vomiting or a possible pregnancy can be a sign of something that needs urgent care — for example an ectopic pregnancy or appendicitis.",
      ["Go to the nearest emergency unit or clinic now.", "Do not eat or drink much until you have been assessed, in case a procedure is needed.", "Take someone with you if you can."],
    );
  }
  if (a.jointWarnings) {
    return {
      level: "prompt",
      title: "See a health worker within the next day or two",
      message: "A hot, red, very swollen joint — or not being able to put weight on it — can be a sign of infection or injury that should be checked soon.",
      steps: ["Visit a clinic or health centre within the next day or two.", "Rest the joint and avoid putting weight on it until then.", "If you develop a fever or feel very unwell, seek care immediately."],
    };
  }
  if (a.suddenSevere || a.faintFeverVomit) {
    return {
      level: "prompt",
      title: "See a health worker soon",
      message: "Your answers suggest this should be checked by a health worker rather than managed at home, even if it starts to settle.",
      steps: ["Arrange to see a nurse, clinical officer or doctor within the next few days.", "Note when it started, how strong it is, and anything that makes it better or worse.", "If it becomes much worse, or you feel faint or feverish, seek urgent care."],
    };
  }
  if (a.persistent) {
    return {
      level: "prompt",
      title: "Arrange a routine assessment",
      message: "Symptoms that are new, getting worse, or lasting more than two weeks deserve a proper assessment — not to frighten you, but so you get clear answers.",
      steps: ["Book a visit with a nurse, clinical officer or doctor.", "Bring your PainEase records — they help the health worker see the pattern.", "If things change suddenly or become severe, seek care sooner."],
    };
  }
  return {
    level: "routine",
    title: "Self-care is reasonable for now",
    message: "Nothing in your answers points to something urgent. Comfort measures and gentle routines are reasonable, while you keep an eye on how things change.",
    steps: ["Try the comfort suggestions and routines in PainEase.", "Stop any routine that makes your symptoms worse.", "Seek care if symptoms become severe, new symptoms appear, or things don't improve."],
  };
}
